def max_value_on_paths(N, grid_values):
    grid = [[0 for _ in range(N)] for _ in range(N)]
    for x, y, value in grid_values:
        if value:
            grid[x][y] = value

    def dfs(x, y, prev_path, max_sum):
        if x == N-1 and y == N-1:
            max_sum[0] = max(max_sum[0], prev_path)
            return

        if x < 0 or y < 0 or x >= N or y >= N:
            return

        for nx, ny in [(x-1, y), (x+1, y), (x, y-1), (x, y+1)]:
            dfs(nx, ny, prev_path + grid[nx][ny], max_sum)

    max_sum = [0]
    dfs(0, 0, 0, max_sum)
    return max_sum[0]

