def cantor_numbering(N: int) -> str:
    i = 1
    k = 0
    while k * (2 * i + 1) < N:
        k += 1
        if N <= k * (2 * i + 1):
            i += 1

    a = (N - 1 - k * (2 * i + 1)) // i + 1
    b = (N - 1 - k * (2 * i + 1)) % i + 1
    return f"{a}/{b}"

def max_product(num_str, N, K):
    from itertools import combinations

    def calculate_product(substring):
        return int(substring) * int(substring[0])

    segments = [num_str[i:i+N] for i in range(N)]
    product = 1

    for combination in combinations(segments, K):
        product *= calculate_product(''.join(combination))

    return product

