def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn):
        if isbn[-1].upper() == 'X':
            isbn = isbn[:-1] + '10'
        sum = 0
        for i in range(1, len(isbn) + 1):
            digit = int(isbn[i - 1])
            weight = 10 if i % 2 == 0 else 1
            sum += digit * weight
        return sum % 11

    if not isbn:
        return "Input is empty"

    expected_checksum = calculate_checksum(isbn)
    actual_checksum = calculate_checksum(isbn[:-1])

    if actual_checksum == expected_checksum:
        return "Right"
    else:
        return isbn[:-1] + str(expected_checksum if actual_checksum % 11 == 1 else 0)

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    aisle_row_positions = [i // K for i in range(M * N)]
    aisle_col_positions = [i // L for i in range(M * N)]

    def count_chatting_pairs(row, col):
