        for pair in chatting_pairs:
            x1, y1, x2, y2 = pair
            if row == x1 or row == x2 or col == y1 or col == y2:
                count += 1
        return count

    def find_optimal_aisles(aisle_positions, total_rows, total_cols):
        max_separations = 0
        best_row_positions = []
        best_col_positions = []
        for i in range(total_rows):
            for j in range(total_cols):
                row_positions = [i + max_separations for i in aisle_positions if aisle_rows[i] == j // K]
                col_positions = [j + max_separations for j in aisle_positions if aisle_cols[j] == i // L]
                total_separations = max(len(row_positions), len(col_positions))
                if total_separations > max_separations:
                    max_separations = total_separations
                    best_row_positions = row_positions
