def count_passing_ways(n: int, m: int) -> int:
    # Initialize a 2D list to store the number of ways for each(student, pass) pair
    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]

    # Base case: There is only one way to pass to any neighbor on the last interval
    for i in range(1, n + 1):
        dp[i][1] = 1

    # Fill the DP table
    for pass_count in range(2, m + 1):
        for student in range(1, n + 1):
            # If the student is at the beginning or end of the circle,
            # there is only one way to pass to the neighbor
            if student == 1 or student == n:
                dp[student][pass_count] = dp[student - 1][pass_count - 1]
            else:
                # The ball can be passed to the left or right neighbor
                dp[student][pass_count] = dp[student - 1][pass_count - 1] + dp[student + 1][pass_count - 1]

    # The result is the number of ways to pass both the first and the last student
    return dp[1][m]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
