        for j in range(n + 1):
            if i == 0 or j == 0:
                DP[i][j] = 0
            elif items[i - 1][0] <= j:
                DP[i][j] = max(items[i - 1][1] + DP[i - 1][j - items[i - 1][0]], DP[i - 1][j])
