def max_energy(beads):
    n = len(beads)
    dp = [0] * n
    for i in range(n):
        if i == 0:
            dp[i] = beads[0] * beads[1]
        elif i == n - 1:
            dp[i] = beads[i] * beads[0]
        else:
            dp[i] = max(dp[i-1], beads[i] * beads[i+1])
    return max(dp)

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    def format_coefficient(coef, x_deg):
        if x_deg == 0:
            return str(abs(coef)) if coef != 1 else ''
        return f'{abs(coef)}x^{x_deg}' if coef != 1 else f'{coef}x'

    result = []
    for i, coef in enumerate(coeffs):
        if coef != 0:
            x_deg = n - i
            result.append(format_coefficient(coef, x_deg) if x_deg > 0 else '')

    return ''.join(result)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(message):
        return "Failed"

    mapping = {}
    for i in range(len(encoded)):
        if encoded[i] not in mapping or mapping[encoded[i]] != original[i]:
            return "Failed"
        mapping[encoded[i]] = original[i]

    decoded = ""
    for char in message:
        if char in mapping:
            decoded += mapping[char]
        else:
            return "Failed"

    return decoded

def largest_prime_factor(n: int) -> int:
    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    divisor = 2
    while divisor * divisor <= n:
        if n % divisor == 0:
            n //= divisor
        else:
            divisor += 1
    return n if is_prime(n) else n

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0  # No partition possible if total sum is less than k*x
    if k == 1:
        return n  # Single part can be n itself
    if n == 1:
        return 0 if k > 1 else 1  # Only one part of 1 if k > 1

    # Use dynamic programming to solve the problem
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dp[i][1] = i  # One part can be i itself
        for j in range(2, k + 1):
            dp[i][j] = dp[i - x][j] + dp[i][j - 1]

    return dp[n][k]

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]

    count = 0
    for i in range(1, int(last / 2) + 1):
        if n == 1:
            count += 1
        else:
            count += count_sequences(n - 1, i, memo)

    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
