def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    if len(A) > len(B) or sorted(A) != sorted(B) or not rules:
        return "NO ANSWER!"

    max_steps = 10
    queue = deque([(A, 0)])
    visited = set()

    while queue:
        current_str, steps = queue.popleft()
        if current_str == B:
            return steps

        if steps >= max_steps:
            continue

        new_chars = [char for char in current_str]
        for rule in rules:
            if rule[0] in new_chars:
                new_chars[new_chars.index(rule[0])] = rule[1]
                new_string = "".join(new_chars)
                if new_string not in visited and len(new_string) <= len(A):
                    visited.add(new_string)
                    queue.append((new_string, steps + 1))

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

