def calculate_arrangements(n: int, m: int, a: List[int]) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            for k in range(1, min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k] % MOD) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key_length = len(key)
    decrypted_text = ""
    key_index = 0

    for char in ciphertext:
        if char.isalpha():
            shift = ord(key[key_index % key_length]) - ord('A')
            decrypted_char = chr(((ord(char) - ord('A') - shift) % 26) + ord('A'))
            decrypted_text += decrypted_char
            key_index += 1
        else:
            decrypted_text += char

    return decrypted_text

def mod_inverse(a, b):
    # Extended Euclidean Algorithm to find the modular multiplicative inverse
    x0, x1, y0, y1 = 0, 1, 1, 0

    while b:
        quotient = a // b
        a, b = b, a % b
        x0, x1 = x1 - quotient * x0, x0
        y0, y1 = y1 - quotient * y0, y1

    if a != 1:
        return None  # Inverse does not exist
    else:
        return (x0 + b) % b

